-- Colors come from lua/core/palette.lua, generated by theme/build.sh.
return {
  'projekt0n/github-nvim-theme',
  name = 'github-theme',
  priority = 1000,
  config = function()
    local p = require('core.palette')
    require('github-theme').setup({
      options = {
        transparent = true,
      },
      specs = {
        github_dark_default = {
          bg1 = p.bg,
          fg1 = p.fg,
          sel0 = p.selection_bg,
          syntax = {
            keyword = p.syn_keyword,
            conditional = p.syn_keyword,
            statement = p.syn_keyword,
            preproc = p.syn_keyword,
            builtin1 = p.syn_keyword,
            string = p.syn_string,
            regex = p.syn_string,
            func = p.syn_func,
            const = p.syn_const,
            number = p.syn_const,
            operator = p.syn_const,
            field = p.syn_const,
            builtin0 = p.syn_const,
            builtin2 = p.syn_const,
            type = p.syn_type,
            tag = p.syn_tag,
            comment = p.syn_comment,
            bracket = p.syn_ident,
            ident = p.syn_ident,
            param = p.syn_ident,
            variable = p.syn_ident,
          },
        },
      },
      groups = {
        github_dark_default = {
          Cursor = { fg = p.bg, bg = p.cursor },
          StatusLine = { fg = p.fg, bg = 'NONE' },
          StatusLineNC = { fg = p.fg_dim, bg = 'NONE' },
          StatusLineTerm = { fg = p.fg, bg = 'NONE' },
          StatusLineTermNC = { fg = p.fg_dim, bg = 'NONE' },
          NeoTreeDirectoryIcon = { fg = p.dir },
          NeoTreeDirectoryName = { fg = p.dir },
          NeoTreeRootName = { fg = p.dir, style = 'bold' },
          NeoTreeSymbolicLinkTarget = { fg = p.symlink, style = 'italic' },
        },
      },
    })
    vim.cmd('colorscheme github_dark_default')
  end,
}
